#!/usr/bin/env bash
# lado-local-setup.sh — gate helpers for the LADO step 7 chain (docs/chains/lado-local-setup.tsv).
#
# Every subcommand prints one success token on its last line and exits 0, or prints why and exits 1.
# Entries call these from one-line CHECKs. Do not edit this file during the chain (gate S*-G0 checks it).
#
#   defs-unchanged                      chain definition, gates and harness match tag lado-step7-chain-def, no local edits
#   go-tests <pkg> <TestName>...        each named top-level test ran and passed           -> GO_TESTS_OK n/n
#   go-tests-isolated <pkg> <Test>...   go-tests with HOME, USERPROFILE, XDG_CONFIG_HOME in a temp dir and
#                                       CLAUDE_CONFIG_DIR, CODEX_HOME unset (Go caches pinned) -> GO_TESTS_OK n/n
#   go-pkg <pkg>...                     go test -count=1 for the packages                  -> GO_PKG_OK
#   go-pkg-isolated <pkg>...            go-pkg with the isolated home of go-tests-isolated -> GO_PKG_OK
#   go-race <pkg>...                    go test -race -count=1 for the packages            -> GO_RACE_OK
#   go-race-isolated <pkg>...           go-race with the isolated home of go-tests-isolated -> GO_RACE_OK
#   go-lint <pkg pattern>...            golangci-lint v2.13.2 like CI, on the patterns     -> GO_LINT_OK
#   go-build                            go build ./... and go vet ./...                    -> GO_BUILD_OK
#   probe <TestName>...                 the real-binary delivery probe (S01) ran and passed -> PROBE_OK n/n
#   no-home-lookups <dir>               no home or tool-folder lookups in non-test Go files -> NO_HOME_LOOKUPS
#   sqlc-clean                          npm run sqlc leaves gen/ unchanged and committed   -> SQLC_CLEAN
#   api-clean                           npm run api leaves openapi.yaml and schema.ts unchanged -> API_CLEAN
#   queries-ascii                       queries/lado_*.sql are ASCII only (sqlc offset bug) -> QUERIES_ASCII
#   vitest <file>...                    vitest run for the files (all must exist)          -> VITEST_OK
#   typecheck                           frontend typecheck and typecheck:e2e               -> TYPECHECK_OK
#   tree-clean                          nothing uncommitted outside ignored state          -> TREE_CLEAN
#   has <file> <fixed string>...        every string occurs in the file                    -> HAS_OK
#   none <path> <fixed string>...       no string occurs in the file or under the directory -> NONE_OK
#   locales <key>...                    every key is in all 8 renderer locale files        -> LOCALES_OK
#   diff-budget <max> <file>...         added+deleted lines in the files since the tag <= max -> BUDGET_OK
#   gitleaks                            gitleaks v7 on main..HEAD with this tree's config (like CI) -> GITLEAKS_OK
set -uo pipefail

ROOT="${CLAUDE_PROJECT_DIR:-$(git rev-parse --show-toplevel 2>/dev/null)}"
cd "$ROOT" || { echo "cannot enter project root: $ROOT"; exit 1; }
TAG="lado-step7-chain-def"
TOOLS="/tmp/claude-1000/-home-code-project-agent-orchestrator-fork/eeda879d-4d21-4b46-a44c-03c90e64d0b5/scratchpad/tools"

fail() { printf '%s\n' "$*"; exit 1; }

# isolated_env runs "$@" with every home and tool-folder variable pointing into a fresh temp dir,
# so a test that reaches for the real ~/.claude, ~/.claude.json or ~/.codex finds nothing there.
# Callers are already in backend/.
isolated_env() {
  local gocache gomodcache gopath tmp rc
  gocache="$(go env GOCACHE)" || return 1
  gomodcache="$(go env GOMODCACHE)" || return 1
  gopath="$(go env GOPATH)" || return 1
  tmp="$(mktemp -d)" || return 1
  mkdir -p "$tmp/home/.config"
  env -u CLAUDE_CONFIG_DIR -u CODEX_HOME -u CLAUDE_SECURESTORAGE_CONFIG_DIR \
    GOCACHE="$gocache" GOMODCACHE="$gomodcache" GOPATH="$gopath" \
    HOME="$tmp/home" USERPROFILE="$tmp/home" XDG_CONFIG_HOME="$tmp/home/.config" \
    "$@"
  rc=$?
  rm -rf "$tmp"
  return $rc
}

count_passed() { # <go test -v output> <names...> -> sets passed, missing
  local out="$1"; shift
  passed=0; missing=()
  for name in "$@"; do
    if grep -qE "^--- PASS: ${name} " <<<"$out"; then passed=$((passed + 1)); else missing+=("$name"); fi
  done
}

sub="${1:-}"; shift || true
case "$sub" in
  defs-unchanged)
    git rev-parse -q --verify "refs/tags/$TAG" >/dev/null || fail "tag $TAG is missing"
    paths=(.claude docs/chains)
    git diff --quiet "$TAG" HEAD -- "${paths[@]}" || { git diff --stat "$TAG" HEAD -- "${paths[@]}"; fail "chain definition or harness changed since $TAG"; }
    dirty="$(git status --porcelain -- "${paths[@]}")"
    [[ -z "$dirty" ]] || { printf '%s\n' "$dirty"; fail "uncommitted changes in chain definition or harness"; }
    echo DEFS_UNCHANGED ;;

  go-tests|go-tests-isolated)
    pkg="${1:-}"; shift || true
    (( $# )) || fail "usage: $sub <pkg> <TestName>..."
    pattern="^($(IFS='|'; printf '%s' "$*"))\$"
    if [[ "$sub" == go-tests-isolated ]]; then
      out="$(cd backend && isolated_env go test -count=1 -v -run "$pattern" "$pkg" 2>&1)"; rc=$?
    else
      out="$(cd backend && go test -count=1 -v -run "$pattern" "$pkg" 2>&1)"; rc=$?
    fi
    count_passed "$out" "$@"
    if (( rc == 0 && passed == $# )); then echo "GO_TESTS_OK $passed/$#"; exit 0; fi
    printf '%s\n' "$out" | tail -60
    fail "not passed: ${missing[*]:-none} (go test rc=$rc)" ;;

  go-pkg|go-pkg-isolated)
    (( $# )) || fail "usage: $sub <pkg>..."
    if [[ "$sub" == go-pkg-isolated ]]; then
      out="$(cd backend && isolated_env go test -count=1 "$@" 2>&1)"; rc=$?
    else
      out="$(cd backend && go test -count=1 "$@" 2>&1)"; rc=$?
    fi
    (( rc == 0 )) || { printf '%s\n' "$out" | tail -60; fail "go test failed (rc=$rc)"; }
    echo GO_PKG_OK ;;

  go-race|go-race-isolated)
    (( $# )) || fail "usage: $sub <pkg>..."
    if [[ "$sub" == go-race-isolated ]]; then
      out="$(cd backend && isolated_env go test -race -count=1 "$@" 2>&1)"; rc=$?
    else
      out="$(cd backend && go test -race -count=1 "$@" 2>&1)"; rc=$?
    fi
    (( rc == 0 )) || { printf '%s\n' "$out" | tail -60; fail "go test -race failed (rc=$rc)"; }
    echo GO_RACE_OK ;;

  go-lint)
    (( $# )) || fail "usage: go-lint <pkg pattern>..."
    out="$(cd backend && go run github.com/golangci/golangci-lint/v2/cmd/golangci-lint@v2.13.2 run --path-mode=abs "$@" 2>&1)"; rc=$?
    (( rc == 0 )) || { printf '%s\n' "$out" | tail -40; fail "golangci-lint failed (rc=$rc)"; }
    echo GO_LINT_OK ;;

  go-build)
    out="$(cd backend && go build ./... 2>&1 && go vet ./... 2>&1)"; rc=$?
    (( rc == 0 )) || { printf '%s\n' "$out" | tail -40; fail "go build or vet failed (rc=$rc)"; }
    echo GO_BUILD_OK ;;

  probe)
    (( $# )) || fail "usage: probe <TestName>..."
    codex="${AO_LADO_SETUP_PROBE_CODEX:-$TOOLS/codex-cli/node_modules/.bin/codex}"
    [[ -x "$codex" ]] || fail "codex binary missing: $codex (set AO_LADO_SETUP_PROBE_CODEX)"
    command -v claude >/dev/null || fail "claude is not on PATH"
    pattern="^($(IFS='|'; printf '%s' "$*"))\$"
    out="$(cd backend && AO_LADO_SETUP_PROBE=1 AO_LADO_SETUP_PROBE_CODEX="$codex" go test -count=1 -v -timeout 15m -run "$pattern" ./internal/service/ladosetup/probe/ 2>&1)"; rc=$?
    count_passed "$out" "$@"
    if grep -qE '^--- SKIP' <<<"$out"; then printf '%s\n' "$out" | grep -E -A3 '^--- SKIP' | head -20; fail "a probe was skipped"; fi
    if (( rc == 0 && passed == $# )); then echo "PROBE_OK $passed/$#"; exit 0; fi
    printf '%s\n' "$out" | tail -80
    fail "probe not passed: ${missing[*]:-none} (go test rc=$rc)" ;;

  no-home-lookups)
    dir="${1:-}"
    [[ -d "$dir" ]] || fail "directory missing: $dir"
    hits="$(grep -rnE 'os\.UserHomeDir\(|os\.Getenv\("(HOME|USERPROFILE|CLAUDE_CONFIG_DIR|CODEX_HOME)"\)|os\.LookupEnv\("(HOME|USERPROFILE|CLAUDE_CONFIG_DIR|CODEX_HOME)"\)' --include='*.go' --exclude='*_test.go' "$dir" | grep -v '/probe/' || true)"
    [[ -z "$hits" ]] || { printf '%s\n' "$hits"; fail "home or tool-folder lookups in $dir (paths must come from the daemon)"; }
    echo NO_HOME_LOOKUPS ;;

  sqlc-clean)
    out="$(npm run sqlc 2>&1)"; rc=$?
    (( rc == 0 )) || { printf '%s\n' "$out" | tail -30; fail "npm run sqlc failed (rc=$rc)"; }
    dirty="$(git status --porcelain -- backend/internal/storage/sqlite/gen)"
    [[ -z "$dirty" ]] || { printf '%s\n' "$dirty"; git diff --stat -- backend/internal/storage/sqlite/gen; fail "sqlc output differs from the commit"; }
    echo SQLC_CLEAN ;;

  api-clean)
    out="$(npm run api 2>&1)"; rc=$?
    (( rc == 0 )) || { printf '%s\n' "$out" | tail -30; fail "npm run api failed (rc=$rc)"; }
    dirty="$(git status --porcelain -- backend/internal/httpd/apispec/openapi.yaml frontend/src/api/schema.ts)"
    [[ -z "$dirty" ]] || { printf '%s\n' "$dirty"; fail "generated API files differ from the commit"; }
    echo API_CLEAN ;;

  queries-ascii)
    hits="$(grep -nP '[^\x00-\x7F]' backend/internal/storage/sqlite/queries/lado_*.sql || true)"
    [[ -z "$hits" ]] || { printf '%s\n' "$hits"; fail "non-ASCII characters in LADO query files"; }
    echo QUERIES_ASCII ;;

  vitest)
    (( $# )) || fail "usage: vitest <file>..."
    for f in "$@"; do [[ -f "frontend/$f" ]] || fail "test file missing: frontend/$f"; done
    out="$(cd frontend && npx vitest run "$@" 2>&1)"; rc=$?
    (( rc == 0 )) || { printf '%s\n' "$out" | tail -60; fail "vitest failed (rc=$rc)"; }
    echo VITEST_OK ;;

  typecheck)
    out="$(cd frontend && npm run typecheck 2>&1 && npm run typecheck:e2e 2>&1)"; rc=$?
    (( rc == 0 )) || { printf '%s\n' "$out" | tail -40; fail "typecheck failed (rc=$rc)"; }
    echo TYPECHECK_OK ;;

  tree-clean)
    dirty="$(git status --porcelain)"
    [[ -z "$dirty" ]] || { printf '%s\n' "$dirty"; fail "uncommitted changes"; }
    echo TREE_CLEAN ;;

  has)
    file="${1:-}"; shift || true
    [[ -f "$file" ]] || fail "file missing: $file"
    (( $# )) || fail "usage: has <file> <fixed string>..."
    for s in "$@"; do grep -qF -- "$s" "$file" || fail "missing in $file: $s"; done
    echo HAS_OK ;;

  none)
    path="${1:-}"; shift || true
    [[ -e "$path" ]] || fail "path missing: $path"
    (( $# )) || fail "usage: none <path> <fixed string>..."
    for s in "$@"; do
      hits="$(grep -rnF -- "$s" "$path" || true)"
      [[ -z "$hits" ]] || { printf '%s\n' "$hits" | head -20; fail "still present under $path: $s"; }
    done
    echo NONE_OK ;;

  locales)
    (( $# )) || fail "usage: locales <key>..."
    for loc in en ko ja zh-CN es fr de pt-BR; do
      f="frontend/src/renderer/i18n/$loc.json"
      [[ -f "$f" ]] || fail "locale file missing: $f"
      for k in "$@"; do grep -qF -- "\"$k\":" "$f" || fail "missing key in $f: $k"; done
    done
    echo LOCALES_OK ;;

  diff-budget)
    max="${1:-}"; shift || true
    [[ "$max" =~ ^[0-9]+$ ]] || fail "usage: diff-budget <max> <file>..."
    (( $# )) || fail "usage: diff-budget <max> <file>..."
    git rev-parse -q --verify "refs/tags/$TAG" >/dev/null || fail "tag $TAG is missing"
    total="$(git diff --numstat "$TAG" HEAD -- "$@" | awk '{a+=$1; d+=$2} END {print a+d+0}')"
    (( total <= max )) || { git diff --numstat "$TAG" HEAD -- "$@"; fail "upstream hook budget exceeded: $total > $max"; }
    echo "BUDGET_OK $total/$max" ;;

  gitleaks)
    bin="${GITLEAKS_BIN:-$TOOLS/gitleaks-bin/gitleaks}"
    [[ -x "$bin" ]] || fail "gitleaks binary missing: $bin (set GITLEAKS_BIN)"
    common="$(git rev-parse --path-format=absolute --git-common-dir)" || fail "cannot find the main repository"
    list="$(mktemp)"; git rev-list main..HEAD > "$list"
    out="$("$bin" --path="${common%/.git}" --commits-file="$list" --config-path="$ROOT/.github/.gitleaks.toml" --redact 2>&1)"; rc=$?
    rm -f "$list"
    (( rc == 0 )) || { printf '%s\n' "$out" | grep -v '^time=' | tail -40; fail "gitleaks found leaks (rc=$rc)"; }
    echo GITLEAKS_OK ;;

  *)
    fail "unknown subcommand: ${sub:-<none>}" ;;
esac
